Hypothesis ACCWS : forall Σ m, ART RT Σ m -> acc asegs m A_SEPS_WS 4.

Local Ltac ul := unfold SEGTOP_A, STACK_WIN, USTACK_TOP, RT_STACK, A_SEPS_WS in *; lia.

Theorem stringRemoveChars_ok : stringRemoveWS_cps RT.
